SHARE_VERSES = ["John 3:16", "Romans 5:8", "Matthew 11:28", "2 Corinthians 5:17", "Romans 6:23", "John 10:10"]


def scripture_refs():
    out = [g["verse"] for g in GOSPEL]
    for s in BIG_STORY:
        out += [s["read"], s["verse"]]
    for q in QUESTIONS:
        out += q["verses"]
    out += [g[2] for g in GLOSSARY]
    out += SHARE_VERSES
    return out
